function MusicPlayerDialog:HandleBackAction()
    ---处理自定义返回事件
    local findChange = false
    if #self.selectedCdIdList ~= #playerDojo:GetSelectedAlbumList() then
        findChange = true
    else
        for _, albumId in ipairs(self.selectedCdIdList) do
            if not playerDojo:CheckAlbumIsSelected(albumId) then
                findChange = true
                break
            end
        end
    end
    if findChange then
        GameUtils.SecondConfirm(localize("是否保存对音乐播放列表的修改？"), function()
            GameUtils.Request(Interfaces.PlayerSetShowAlbum, {albumIds = table.concat(self.selectedCdIdList, ",")}, function(request, response)
                if tonumber(response.errCode) == 0 then
                    playerDojo:UpdateSelectedAlbumMap(self.selectedCdIdMap)
                    UIModule.BackDialog()
                end
            end)
        end, function()
            UIModule.BackDialog()
        end)
    else
        UIModule.BackDialog()
    end
end

