function MusicPlayerDialog:InitAllCdInfo()
    self.cdIdDt           = {}
    self.selectedCdIdList = clone(playerDojo:GetSelectedAlbumList())
    self.selectedCdIdMap  = clone(playerDojo:GetSelectedAlbumMap())

    local allAlbumIdList = {}
    for _, cdData in pairs(CfUtils.GetCf(AutoIds.IdSetting899, "MusicPlayerVo", true)) do
        table.insert(allAlbumIdList, cdData.id)
    end
    table.sort(allAlbumIdList, function(albumIDA, albumIDB)
        if playerDojo:CheckAlbumIsUnlocked(albumIDA) ~= playerDojo:CheckAlbumIsUnlocked(albumIDB) then
            return playerDojo:CheckAlbumIsUnlocked(albumIDA)
        else
            return albumIDA < albumIDB
        end
    end)
    for index, id in ipairs(allAlbumIdList) do
        table.insert(self.cdIdDt, {id = id, index = index, cb = Bind(self, self.OnClickFavoriteNode), idMap = self.selectedCdIdMap})
    end
    --Events.Broadcast(Constants.EventNames.MainHomeUpdateCDList, {data = self.selectedCdIdList, needAnim = true})

    self.ChapterList:InitListView(#self.cdIdDt, self.cdIdDt)
    self.ChapterList.OnIndexChanged = Bind(self, self.OnSelectCD)

    local musicId = playerComponent:GetCurrentMusicId()
    local selectIndex = 0
    for i, v in pairs(self.cdIdDt) do
        if checkNumber(v.id) == musicId then
            selectIndex = checkNumber(v.index) - 1
            break
        end
    end
    self:OnSelectCD(selectIndex)
    self:FillMusicList()
    self.ChapterList:MovePanelToIndex(selectIndex)
end

function MusicPlayerDialog:OnSelectCD(index)
    self._curInd = index
    self.selectedId = self.cdIdDt[index + 1].id
    --红点状态
    if PlayerInfoUtils.CheckIsCDHasNewById(self.selectedId) then
        PlayerInfoUtils.UpdateCDNewStateById(self.selectedId, false)
    end
    self:FillSelectInfo()
    local musicId = playerComponent:GetCurrentMusicId()
    ---@type MusicPlayerVo
    local cdVo = CfUtils.GetCfVo(AutoIds.IdSetting899, "MusicPlayerVo", self.selectedId)
    if playerDojo:CheckAlbumIsUnlocked(self.selectedId) then
        if musicId ~= checkNumber(cdVo.id) then
            ---进行音乐播放
            print(musicId, cdVo.id)
            local playId = playerComponent:GetRandomMusic(true, cdVo.id)
            ---@type MusicPlayerVo
            local musicVo = CfUtils.GetCfVo(AutoIds.IdSetting899, "MusicPlayerVo", playId)
            CriWareUtils.PlayMusicById(musicVo.musicId)
        end
    end
end

function MusicPlayerDialog:FillSelectInfo()
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting899, "MusicPlayerVo", self.selectedId)
    if not vo then
        return
    end
    local isUnlock = playerDojo:CheckAlbumIsUnlocked(self.selectedId)
    CfUtils.SetUISwitchImage(self.ImgTitle, isUnlock and 1 or 2)
    CfUtils.SetActive(self.LockNode, not isUnlock)
    CfUtils.SetActive(self.BtnCollect, isUnlock)
    CfUtils.SetActive(self.TxtTitle2, isUnlock)
    CfUtils.SetUISwitchImage(self.BtnCollect, self.selectedCdIdMap[checkInt(self.selectedId)] and 2 or 1)

    CfUtils.FillText(self.TxtTitle1, vo.name)
    if isUnlock then
        CfUtils.FillText(self.TxtTitle2, vo.unlockDesc)
    else
        CfUtils.FillText(self.TxtLockContent, vo.lockDesc)
    end
end

function MusicPlayerDialog:OnClickFavoriteNode()
    local id = self.selectedId
    if not playerDojo:CheckAlbumIsUnlocked(id) then
        GameUtils.Toast(localize("未解锁"))
        return
    end

    if self.selectedCdIdMap[checkInt(id)] ~= nil then
        -- remove data
        if #self.selectedCdIdList <= 1 then
            GameUtils.Toast(localize("至少保留一首单曲噢"))
        else
            self.hasChange_ = true
            table.removebyvalue(self.selectedCdIdList, id)
            self.selectedCdIdMap[checkInt(id)] = nil
            Events.Broadcast(Constants.EventNames.MainHomeUpdateCDList, {data = self.selectedCdIdList})
        end
    else
        local maxNo = PlayerInfoUtils.GetMaxCDSetNum()
        if #self.selectedCdIdList >= maxNo then
            GameUtils.Toast(localize("最多添加_num_首单曲噢", {_num_ = maxNo}))
        else
            self.hasChange_ = true
            table.insert(self.selectedCdIdList, id)
            self.selectedCdIdMap[checkInt(id)] = true
            Events.Broadcast(Constants.EventNames.MainHomeUpdateCDList, {data = self.selectedCdIdList})
        end
    end
    CfUtils.SetUISwitchImage(self.BtnCollect, self.selectedCdIdMap[checkInt(self.selectedId)] and 2 or 1)
    self:FillMusicList()

    local go = self.ChapterList:GetShownItemByItemIndex(checkNumber(self._curInd))
    if go then
        local scr = CfUtils.GetLuaScr(go, "Game.UI.MusicPlayer.MusicPlayerCell")
        if scr then
            scr:UpdateContent(self.cdIdDt[self._curInd + 1])
        end
    end
end

function MusicPlayerDialog:FillMusicList()
    for k, v in pairs(self.selectedCdIdList) do
        local go = self.Layout.transform:Find("go"..k)
        if not go then
            go = CfUtils.InstantiateGo(self.TxtNumber1, self.Layout)
            go.name = "go"..k
        end

        CfUtils.FillText(go, k)
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting899, "MusicPlayerVo", v)
        if vo then
            CfUtils.FillText(go.transform:Find("TxtMusicName"), vo.name) 
        end
        CfUtils.SetActive(go, true)
    end

    if self.Layout.childCount > table.count(self.selectedCdIdList) then
        for i = table.count(self.selectedCdIdList) + 1, self.Layout.childCount do
            local go = self.Layout.transform:Find("go"..i)
            CfUtils.SetActive(go, false)
        end
    end
    CfUtils.FillText(self.TxtNum, string.format("%s/%s", #self.selectedCdIdList, PlayerInfoUtils.GetMaxCDSetNum()))
end

function MusicPlayerDialog:UpdateCollectNum()
    local ownedNum = playerDojo:GetOwnedAlbumNum()
    local totalNum = #self.cdIdDt
    CfUtils.FillText(self.TxtNumber, string.format("%s/%s", ownedNum, totalNum))
end

return MusicPlayerDialog